(6769232, 1014182, 8759, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by mariuca:</b></div><hr/><i> Ha, ha, imagine if you would have started work earlier! Bravo Tibi! </i></td></tr></table> <br/> <br/>It''s the end of the line. Earlier they would have kicked me out immediately. The man in the background was actually running towards me to make sure I leave the train ( Get out know! He seemed to shout) . I only had time to take 2 shots but i practiced the angle (with people in frame) for couple of stops to be ready when Empty.</td>', 'Originally posted by mariuca: Ha, ha, imagine if you would have started work earlier! Bravo Tibi!   It''s the end of the line. Earlier they would have kicked me out immediately. The man in the background was actually running towards me to make sure I leave the train ( Get out know! He seemed to shout) . I only had time to take 2 shots but i practiced the angle (with people in frame) for couple of stops to be ready when Empty.', '2012-05-14 21:45:02.000000', NULL, 0),
(6769234, 1013883, 11769, '<td valign="top">Pure.</td>', 'Pure.', '2012-05-14 21:50:26.000000', NULL, 0),
(6769238, 1013598, 30982, '<td valign="top">So now you must figure how to get a scanner that records exif.  :-)  Still an awesome image and an interesting new angle to your creativity!</td>', 'So now you must figure how to get a scanner that records exif.  :-)  Still an awesome image and an interesting new angle to your creativity!', '2012-05-14 22:00:11.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6769246, 1014147, 97225, '<td valign="top">Congratulations, Wendy! Fantastic shot and I so admire your perseverance and dedication. 1200 shots, wow, can you imagine doing that with film?!</td>', 'Congratulations, Wendy! Fantastic shot and I so admire your perseverance and dedication. 1200 shots, wow, can you imagine doing that with film?!', '2012-05-14 22:23:57.000000', NULL, 0),
(6769249, 1014182, 97225, '<td valign="top">Congratulations on the red. Excellent shot, and yes, so remarkably clean. No littering, no loitering - it seems those policies work well.</td>', 'Congratulations on the red. Excellent shot, and yes, so remarkably clean. No littering, no loitering - it seems those policies work well.', '2012-05-14 22:29:37.000000', NULL, 0),
